head.script:
scwin.gVar = {
    "cValidator" : "",
    "cReadOnly" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > validator]<br/>Secret 컴포넌트에서 포커스가 해제될때 입력값 검증을 처리할 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "validate() 메소드에 의한 입력값 유효성 체크와 별개로 사용자가 입력값을 검증하기 위한 함수를 설정합니다.",
        "입력값 검증을 처리할 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 파라미터로 입력값과 대상 컴포넌트의 렌더링 ID 가 전달됩니다.",
        "사용자 정의 함수의 반환값이 새로운 입력값으로 적용됩니다.",
        "사용자 정의 함수가 수행된 후 onblur 이벤트가 발생합니다.",
        "사용자 정의 함수의 반환값으로 입력값이 변경되면 onchange -> onviewchange -> onblur 순으로 이벤트가 발생합니다.",
        "컴포넌트에서 포커스가 해제될때가 아니면 validator 속성은 적용되지 않습니다.",
        "즉, 컴포넌트가 읽기 전용(readonly) 상태이거나 setValue() 메소드로 입력값을 설정하는 경우 사용자 정의 함수는 실행되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_validator.setValue("scwin.fn_validator");
    con_readOnly.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트(초기값 secret)이며 validator 와 readOnly 는 위 조건에서 선택합니다\n[절차] 조건 선택 -> Target 재생성 -> target1 클릭하여 값 입력 후 바깥 영역 클릭 / setValue, validate 버튼도 각각 클릭 / readOnly=true 는 target1 클릭 후 바깥 영역 클릭\n[확인] 결과창의 사용자 정의 함수 실행 줄 출현 여부와 파라미터 val, id / 이어지는 이벤트 줄의 순서와 입력값"', '', 'label1');

    // 조건 설정
    scwin.gVar["cValidator"] = con_validator.getValue();
    scwin.gVar["cReadOnly"] = con_readOnly.getText();

    let properties = {
        validator : scwin.gVar["cValidator"],
        readOnly : scwin.gVar["cReadOnly"],
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onchange", "onviewchange", "onblur"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, eList);
}



// 현재 입력값 (password 라 화면으로 셀 수 없으므로 글자 수 병기)
scwin.fn_value = function () {
    let strValue = target1.getValue();

    if (strValue === undefined || strValue === null)
        return String(strValue);

    return strValue + " (" + strValue.length + "자)";
}



// validator 로 설정되는 사용자 정의 함수 (공통 판 common_P_validator_1 과 동일 형태) - validation 2, 3, 4 판정 출력
scwin.fn_validator = function (val, id) {
    let rtn = "id : " + id + ", val : " + val;

    wf_body_bottom.getObj("scwin").setReturnValue("사용자 정의 함수 실행 -> 파라미터 val : " + val + " (" + val.length + "자) / 파라미터 id : " + id + " -> 반환값 : " + rtn + " (" + rtn.length + "자)");

    return rtn;
}



// 테스트 샘플의 이벤트 처리 (값 변경) - validation 6 판정 출력
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onchange 이벤트 발생");
}



// 테스트 샘플의 이벤트 처리 (표시값 변경) - validation 6 판정 출력
scwin.target1_onviewchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onviewchange 이벤트 발생");
}



// 테스트 샘플의 이벤트 처리 (포커스 해제) - validation 4, 5, 6 판정 출력
scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onblur 이벤트 발생 -> 입력값 : " + scwin.fn_value());
}



// setValue 로 입력값 설정 (포커스 해제가 아닌 경로) - validation 7, 8 판정 출력
scwin.btn_setValue_onclick = function (e) {
    // 설정한 값이 그대로 남아 있으면(반환 문자열 형태로 바뀌지 않으면) 사용자 정의 함수를 거치지 않은 것
    target1.setValue("secret2");

    wf_body_bottom.getObj("scwin").setReturnValue("setValue 실행 -> 입력값 : " + scwin.fn_value());
}



// validate 로 유효성 체크 실행 (사용자 정의 함수와 별개임을 대비) - validation 1, 7 판정 출력
scwin.btn_validate_onclick = function (e) {
    let bReturn = target1.validate();

    wf_body_bottom.getObj("scwin").setReturnValue("validate 실행 -> 반환값 : " + bReturn + " / 입력값 : " + scwin.fn_value());
}
